139	function render() {
140	  els.timeDisplay.textContent = formatTime(remaining);
141	  updateModeClass();
142	  setRingProgress();
143	  els.statToday.textContent = String(loadTodayCount());
144	  els.statCycle.textContent = cycleLabel();
145	  els.btnPrimary.textContent = running ? '暂停' : remaining === totalSeconds ? '开始' : '继续';
146	  if (running) {
147	    els.phaseHint.textContent = mode === MODES.FOCUS ? '保持专注' : '放松一下';
148	  } else if (mode === MODES.LONG) {
149	    els.phaseHint.textContent = '长休之后将开始新一轮';
150	  } else if (mode === MODES.SHORT) {
151	    els.phaseHint.textContent = '准备进入下一段专注';
152	  } else {
153	    els.phaseHint.textContent = '准备开始';
154	  }
155	  updateDockBadge();
156	}
