158	function playAlarmRing() {
159	  try {
160	    const Ctx = window.AudioContext || window.webkitAudioContext;
161	    if (!Ctx) return;
162	    const ctx = new Ctx();
163	    ctx.resume().catch(() => {});
164	
165	    const master = ctx.createGain();
166	    master.gain.value = 0.16;
167	    master.connect(ctx.destination);
168	
169	    const focusEnd = mode === MODES.FOCUS;
170	    const hi = focusEnd ? 932 : 784;
171	    const lo = focusEnd ? 698.46 : 587.33;
172	
173	    function scheduleBeep(start, freq) {
174	      const dur = 0.11;
175	      const o = ctx.createOscillator();
176	      const g = ctx.createGain();
177	      o.type = 'square';
178	      o.frequency.value = freq;
179	      g.gain.setValueAtTime(0.0001, start);
180	      g.gain.exponentialRampToValueAtTime(0.32, start + 0.01);
181	      g.gain.exponentialRampToValueAtTime(0.0001, start + dur);
182	      o.connect(g);
183	      g.connect(master);
184	      o.start(start);
185	      o.stop(start + dur + 0.02);
186	    }
187	
188	    let t = ctx.currentTime + 0.05;
189	    const groups = 6;
190	    for (let g = 0; g < groups; g += 1) {
191	      scheduleBeep(t, hi);
192	      t += 0.19;
193	      scheduleBeep(t, lo);
194	      t += 0.19;
195	      scheduleBeep(t, hi);
196	      t += 0.19;
197	      t += 0.36;
198	    }
199	
200	    const stopAt = (t - ctx.currentTime + 0.4) * 1000;
201	    setTimeout(() => {
202	      ctx.close().catch(() => {});
203	    }, Math.max(0, stopAt));
204	  } catch {
205	    /* ignore */
206	  }
207	}
