223	  if (slot >= 3) {
224	    mode = MODES.LONG;
225	    slot = 0;
226	    saveSlot(0);
227	  } else {
228	    mode = MODES.SHORT;
229	    slot += 1;
230	    saveSlot(slot);
231	  }
232	}
233	
234	function goToFocusFromBreak() {
235	  mode = MODES.FOCUS;
236	}
237	
238	function onTimerComplete() {
239	  running = false;
240	  clearInterval(timerId);
241	  timerId = null;
242	  playAlarmRing();
243	
244	  if (mode === MODES.FOCUS) {
245	    bumpTodayCount();
246	    notify('专注结束', '休息一会儿吧。');
247	    afterFocusCompleted();
248	  } else {
249	    notify('休息结束', '开始下一个番茄。');
250	    goToFocusFromBreak();
251	  }
252	  applyModeDurations();
253	  remaining = totalSeconds;
254	  render();
255	}
256	
257	function tick() {
258	  remaining -= 1;
259	  if (remaining <= 0) {
260	    remaining = 0;
261	    onTimerComplete();
262	    return;
263	  }
264	  render();
265	}
266	
267	function startTimer() {
268	  if (timerId) clearInterval(timerId);
269	  running = true;
270	  timerId = setInterval(tick, 1000);
271	  render();
272	}
273	
274	function pauseTimer() {
275	  running = false;
276	  if (timerId) clearInterval(timerId);
277	  timerId = null;
278	  render();
279	}
280	
281	function resetPhase() {
282	  pauseTimer();
283	  applyModeDurations();
284	  remaining = totalSeconds;
285	  render();
286	}
287	
288	function skipPhase() {
289	  pauseTimer();
290	  if (mode === MODES.FOCUS) {
291	    if (slot >= 3) {
292	      mode = MODES.LONG;
293	      slot = 0;
294	      saveSlot(0);
295	    } else {
296	      mode = MODES.SHORT;
297	    }
298	  } else {
299	    goToFocusFromBreak();
300	  }
301	  applyModeDurations();
302	  remaining = totalSeconds;
303	  render();
304	}
305	
306	els.btnPrimary.addEventListener('click', () => {
