const MODES = {
  FOCUS: 'focus',
  SHORT: 'short',
  LONG: 'long',
};

const RING_LEN = 2 * Math.PI * 88;

const els = {
  modeLabel: document.getElementById('modeLabel'),
  timeDisplay: document.getElementById('timeDisplay'),
  phaseHint: document.getElementById('phaseHint'),
  ringProgress: document.getElementById('ringProgress'),
  btnPrimary: document.getElementById('btnPrimary'),
  btnReset: document.getElementById('btnReset'),
  btnSkip: document.getElementById('btnSkip'),
  chkAlwaysOnTop: document.getElementById('chkAlwaysOnTop'),
  statToday: document.getElementById('statToday'),
  statCycle: document.getElementById('statCycle'),
  btnSettings: document.getElementById('btnSettings'),
  dlgSettings: document.getElementById('dlgSettings'),
  setWork: document.getElementById('setWork'),
  setShort: document.getElementById('setShort'),
  setLong: document.getElementById('setLong'),
  btnCancelSettings: document.getElementById('btnCancelSettings'),
};

const STORAGE_KEYS = {
  work: 'pomodoro_work_min',
  short: 'pomodoro_short_min',
  long: 'pomodoro_long_min',
  today: 'pomodoro_today_count',
  todayDate: 'pomodoro_today_date',
  slot: 'pomodoro_block_slot',
  alwaysOnTop: 'pomodoro_always_on_top',
};

function loadSettings() {
  const w = Number(localStorage.getItem(STORAGE_KEYS.work)) || 25;
  const s = Number(localStorage.getItem(STORAGE_KEYS.short)) || 5;
  const l = Number(localStorage.getItem(STORAGE_KEYS.long)) || 15;
  return {
    workMin: Math.min(120, Math.max(1, w)),
    shortMin: Math.min(60, Math.max(1, s)),
    longMin: Math.min(60, Math.max(1, l)),
  };
}

function saveSettings(workMin, shortMin, longMin) {
  localStorage.setItem(STORAGE_KEYS.work, String(workMin));
  localStorage.setItem(STORAGE_KEYS.short, String(shortMin));
  localStorage.setItem(STORAGE_KEYS.long, String(longMin));
}

function todayKey() {
  const d = new Date();
  return `${d.getFullYear()}-${d.getMonth() + 1}-${d.getDate()}`;
}

function loadTodayCount() {
  const key = localStorage.getItem(STORAGE_KEYS.todayDate);
  if (key !== todayKey()) {
    localStorage.setItem(STORAGE_KEYS.todayDate, todayKey());
    localStorage.setItem(STORAGE_KEYS.today, '0');
    return 0;
  }
  return Number(localStorage.getItem(STORAGE_KEYS.today)) || 0;
}

function bumpTodayCount() {
  const n = loadTodayCount() + 1;
  localStorage.setItem(STORAGE_KEYS.todayDate, todayKey());
  localStorage.setItem(STORAGE_KEYS.today, String(n));
  return n;
}

function loadSlot() {
  return Math.min(3, Math.max(0, Number(localStorage.getItem(STORAGE_KEYS.slot)) || 0));
}

function saveSlot(i) {
  localStorage.setItem(STORAGE_KEYS.slot, String(i));
}

let settings = loadSettings();
let mode = MODES.FOCUS;
let totalSeconds = settings.workMin * 60;
let remaining = totalSeconds;
let running = false;
let timerId = null;
let slot = loadSlot();

function modeLabelText() {
  if (mode === MODES.FOCUS) return '专注';
  if (mode === MODES.SHORT) return '短休息';
  return '长休息';
}

function updateModeClass() {
  els.modeLabel.textContent = modeLabelText();
  els.modeLabel.classList.remove('short', 'long');
  els.ringProgress.classList.remove('short', 'long');
  if (mode === MODES.SHORT) {
    els.modeLabel.classList.add('short');
    els.ringProgress.classList.add('short');
  } else if (mode === MODES.LONG) {
    els.modeLabel.classList.add('long');
    els.ringProgress.classList.add('long');
  }
}

function formatTime(sec) {
  const m = Math.floor(sec / 60);
  const s = sec % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

function setRingProgress() {
  const p = totalSeconds > 0 ? remaining / totalSeconds : 0;
  els.ringProgress.style.strokeDashoffset = String(RING_LEN * (1 - p));
}

function updateDockBadge() {
  if (!window.pomodoro?.setDockBadge) return;
  if (running) {
    window.pomodoro.setDockBadge(formatTime(remaining));
  } else {
    window.pomodoro.setDockBadge('');
  }
}

function cycleLabel() {
  if (mode === MODES.LONG) {
    return '1';
  }
  return `${slot + 1}`;
}

function render() {
  els.timeDisplay.textContent = formatTime(remaining);
  updateModeClass();
  setRingProgress();
  els.statToday.textContent = String(loadTodayCount());
  els.statCycle.textContent = cycleLabel();
  els.btnPrimary.textContent = running ? '暂停' : remaining === totalSeconds ? '开始' : '继续';
  if (running) {
    els.phaseHint.textContent = mode === MODES.FOCUS ? '保持专注' : '放松一下';
  } else if (mode === MODES.LONG) {
    els.phaseHint.textContent = '长休之后将开始新一轮';
  } else if (mode === MODES.SHORT) {
    els.phaseHint.textContent = '准备进入下一段专注';
  } else {
    els.phaseHint.textContent = '准备开始';
  }
  updateDockBadge();
}

function playAlarmRing() {
  try {
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    const ctx = new Ctx();
    ctx.resume().catch(() => {});

    const master = ctx.createGain();
    master.gain.value = 0.16;
    master.connect(ctx.destination);

    const focusEnd = mode === MODES.FOCUS;
    const hi = focusEnd ? 932 : 784;
    const lo = focusEnd ? 698.46 : 587.33;

    function scheduleBeep(start, freq) {
      const dur = 0.11;
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.type = 'square';
      o.frequency.value = freq;
      g.gain.setValueAtTime(0.0001, start);
      g.gain.exponentialRampToValueAtTime(0.32, start + 0.01);
      g.gain.exponentialRampToValueAtTime(0.0001, start + dur);
      o.connect(g);
      g.connect(master);
      o.start(start);
      o.stop(start + dur + 0.02);
    }

    let t = ctx.currentTime + 0.05;
    const groups = 6;
    for (let g = 0; g < groups; g += 1) {
      scheduleBeep(t, hi);
      t += 0.19;
      scheduleBeep(t, lo);
      t += 0.19;
      scheduleBeep(t, hi);
      t += 0.19;
      t += 0.36;
    }

    const stopAt = (t - ctx.currentTime + 0.4) * 1000;
    setTimeout(() => {
      ctx.close().catch(() => {});
    }, Math.max(0, stopAt));
  } catch {
    /* ignore */
  }
}

async function notify(title, body) {
  if (window.pomodoro?.notify) {
    await window.pomodoro.notify(title, body);
  }
}

function applyModeDurations() {
  if (mode === MODES.FOCUS) totalSeconds = settings.workMin * 60;
  else if (mode === MODES.SHORT) totalSeconds = settings.shortMin * 60;
  else totalSeconds = settings.longMin * 60;
  remaining = totalSeconds;
}

function afterFocusCompleted() {
  if (slot >= 3) {
    mode = MODES.LONG;
    slot = 0;
    saveSlot(0);
  } else {
    mode = MODES.SHORT;
    slot += 1;
    saveSlot(slot);
  }
}

function goToFocusFromBreak() {
  mode = MODES.FOCUS;
}

function onTimerComplete() {
  running = false;
  clearInterval(timerId);
  timerId = null;
  playAlarmRing();

  if (mode === MODES.FOCUS) {
    bumpTodayCount();
    notify('专注结束', '休息一会儿吧。');
    afterFocusCompleted();
  } else {
    notify('休息结束', '开始下一个番茄。');
    goToFocusFromBreak();
  }
  applyModeDurations();
  remaining = totalSeconds;
  render();
}

function tick() {
  remaining -= 1;
  if (remaining <= 0) {
    remaining = 0;
    onTimerComplete();
    return;
  }
  render();
}

function startTimer() {
  if (timerId) clearInterval(timerId);
  running = true;
  timerId = setInterval(tick, 1000);
  render();
}

function pauseTimer() {
  running = false;
  if (timerId) clearInterval(timerId);
  timerId = null;
  render();
}

function resetPhase() {
  pauseTimer();
  applyModeDurations();
  remaining = totalSeconds;
  render();
}

function skipPhase() {
  pauseTimer();
  if (mode === MODES.FOCUS) {
    if (slot >= 3) {
      mode = MODES.LONG;
      slot = 0;
      saveSlot(0);
    } else {
      mode = MODES.SHORT;
    }
  } else {
    goToFocusFromBreak();
  }
  applyModeDurations();
  remaining = totalSeconds;
  render();
}

els.btnPrimary.addEventListener('click', () => {
  if (running) pauseTimer();
  else startTimer();
});

els.btnReset.addEventListener('click', () => {
  resetPhase();
});

els.btnSkip.addEventListener('click', () => {
  skipPhase();
});

els.chkAlwaysOnTop.addEventListener('change', () => {
  const on = els.chkAlwaysOnTop.checked;
  localStorage.setItem(STORAGE_KEYS.alwaysOnTop, on ? '1' : '0');
  if (window.pomodoro?.setAlwaysOnTop) {
    window.pomodoro.setAlwaysOnTop(on);
  }
});

els.btnSettings.addEventListener('click', () => {
  els.setWork.value = String(settings.workMin);
  els.setShort.value = String(settings.shortMin);
  els.setLong.value = String(settings.longMin);
  els.dlgSettings.showModal();
});

els.btnCancelSettings.addEventListener('click', () => {
  els.dlgSettings.returnValue = '';
  els.dlgSettings.close();
});

els.dlgSettings.addEventListener('close', () => {
  if (els.dlgSettings.returnValue !== 'save') return;
  const w = Number(els.setWork.value);
  const s = Number(els.setShort.value);
  const l = Number(els.setLong.value);
  if (![w, s, l].every((n) => Number.isFinite(n) && n > 0)) return;
  settings = {
    workMin: Math.min(120, Math.max(1, Math.round(w))),
    shortMin: Math.min(60, Math.max(1, Math.round(s))),
    longMin: Math.min(60, Math.max(1, Math.round(l))),
  };
  saveSettings(settings.workMin, settings.shortMin, settings.longMin);
  pauseTimer();
  applyModeDurations();
  remaining = totalSeconds;
  render();
});

(function init() {
  applyModeDurations();
  remaining = totalSeconds;
  els.ringProgress.style.strokeDasharray = String(RING_LEN);
  const aot = localStorage.getItem(STORAGE_KEYS.alwaysOnTop) === '1';
  els.chkAlwaysOnTop.checked = aot;
  if (window.pomodoro?.setAlwaysOnTop) {
    window.pomodoro.setAlwaysOnTop(aot);
  }
  slot = loadSlot();
  render();
})();

