  --bg: #16161e;
  --bg-elevated: #1f2335;
  --text: #c0caf5;
  --text-muted: #565f89;
  --accent: #f7768e;
  --accent-dim: #bb616a;
  --focus: #7aa2f7;
  --short: #9ece6a;
  --long: #bb9af7;
  --ring-bg: #292e42;
  font-family:
    'SF Pro Text',
    'PingFang SC',
    'Microsoft YaHei',
    system-ui,
    sans-serif;
}

html,
body {
  margin: 0;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  -webkit-font-smoothing: antialiased;
  user-select: none;
}

body {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.titlebar {
  height: 36px;
  -webkit-app-region: drag;
  flex-shrink: 0;
}

.app {
  flex: 1 1 auto;
  min-height: 0;
  padding: 0 clamp(14px, 3vw, 28px) clamp(12px, 2vh, 20px);
  display: flex;
  flex-direction: column;
  align-items: stretch;
}

.mode-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.mode-label {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: none;
  padding: 6px 12px;
  border-radius: 999px;
  background: var(--bg-elevated);
  color: var(--focus);
}

.mode-label.short {
  color: var(--short);
}

.mode-label.long {
  color: var(--long);
}

.btn-icon {
  -webkit-app-region: no-drag;
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-size: 18px;
  cursor: pointer;
  padding: 6px 10px;
  border-radius: 8px;
}

.btn-icon:hover {
  color: var(--text);
  background: var(--bg-elevated);
}

.clock-stage {
  flex: 1 1 0;
  min-height: 0;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4px 0 8px;
  container-type: size;
  container-name: stage;
}

.clock-wrap {
  position: relative;
  box-sizing: border-box;
  width: min(96cqw, 96cqh, 420px);
  max-width: 100%;
  aspect-ratio: 1;
  height: auto;
  margin: 0 auto;
}

.ring {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.ring-bg {
  fill: none;
  stroke: var(--ring-bg);
  stroke-width: 10;
}

.ring-progress {
  fill: none;
  stroke: var(--accent);
  stroke-width: 10;
  stroke-linecap: round;
  stroke-dasharray: 553.1;
  stroke-dashoffset: 0;
  transition: stroke-dashoffset 0.35s ease, stroke 0.3s ease;
}

.ring-progress.short {
  stroke: var(--short);
}

.ring-progress.long {
  stroke: var(--long);
}

.clock-inner {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.time-display {
  font-size: clamp(26px, 22cqmin, 52px);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.04em;
  line-height: 1.1;
}

.phase-hint {
  margin-top: clamp(4px, 1.5cqmin, 10px);
  font-size: clamp(11px, 4.2cqmin, 14px);
  color: var(--text-muted);
  text-align: center;
  padding: 0 6px;
}

.controls {
  display: flex;
  gap: clamp(6px, 1.8vmin, 12px);
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: clamp(8px, 1.8vmin, 14px);
}

.btn {
  -webkit-app-region: no-drag;
  border: 1px solid var(--ring-bg);
  background: var(--bg-elevated);
  color: var(--text);
  padding: clamp(8px, 1.8vmin, 12px) clamp(12px, 3vmin, 20px);
  border-radius: 10px;
  font-size: clamp(12px, 2.2vmin, 15px);
  cursor: pointer;
}

.btn:hover {
  border-color: var(--text-muted);
}

.btn-primary {
  background: linear-gradient(145deg, var(--accent), var(--accent-dim));
  border-color: transparent;
  color: #1a1b26;
  font-weight: 600;
}

.btn-primary:hover {
  filter: brightness(1.06);
}

.checkbox-row {
  -webkit-app-region: no-drag;
  display: flex;
  align-items: center;
  gap: 8px;
  justify-content: center;
  font-size: 13px;
  color: var(--text-muted);
  cursor: pointer;
  margin-bottom: 16px;
}

.checkbox-row input {
  accent-color: var(--accent);
}

.stats {
  margin-top: auto;
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: var(--text-muted);
  padding-top: 8px;
  border-top: 1px solid var(--ring-bg);
}

.stats strong {
  color: var(--text);
  font-weight: 600;
}

.modal {
  border: none;
  border-radius: 14px;
  padding: 0;
  background: var(--bg-elevated);
  color: var(--text);
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.45);
}

.modal::backdrop {
  background: rgba(0, 0, 0, 0.45);
}

.modal-inner {
  padding: 20px 22px;
  width: 280px;
}

.modal-inner h2 {
  margin: 0 0 16px;
  font-size: 16px;
  font-weight: 600;
}

.modal-inner label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
  font-size: 13px;
  gap: 12px;
}

.modal-inner input[type='number'] {
  width: 72px;
  padding: 8px 10px;
  border-radius: 8px;
  border: 1px solid var(--ring-bg);
  background: var(--bg);
  color: var(--text);
  font-size: 14px;
}

.modal-actions {
  display: flex;
  gap: 10px;
  margin-top: 18px;
  justify-content: flex-end;
}

